import 'package:freezed_annotation/freezed_annotation.dart';

part 'home_view_state.freezed.dart';

/// What Home shows that can change: whether there is a saved game to
/// continue ([canContinue]), so Home offers Continue.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class HomeViewState with _$HomeViewState {
  const factory HomeViewState({required bool canContinue}) = _HomeViewState;
}
